function Indicator({
  keepMounted,
  render,
  animation,
  transition,
  exitTransition,
  ...props
}: Indicator.Props) {
  const look = useCheckAnimation(animation);
  if (render)
    return (
      <CheckboxPrimitive.Indicator
        {...props}
        keepMounted={keepMounted}
        render={render}
      />
