'use client';

import * as React from 'react';
import { motion, type HTMLMotionProps, type Transition } from 'motion/react';

import { getStrictContext } from '../../../utils/strict-context';
import {
  ReducedMotionConfig,
  useMotionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';
import { Slot, type WithAsChild } from '../../slot';
import { SCALE_SPRING, TAP_SCALE } from '../_button';

const RIPPLE_TRANSITION: Transition = { duration: 0.6, ease: 'easeOut' };

type Ripple = {
  id: number;
  x: number;
  y: number;
};

type RippleButtonContextType = {
  ripples: Ripple[];
  setRipples: (ripples: Ripple[]) => void;
};

const [RippleButtonProvider, useRippleButton] =
  getStrictContext<RippleButtonContextType>('RippleButtonContext');

type RippleButtonProps = WithAsChild<
  HTMLMotionProps<'button'> & {
    hoverScale?: number;
    tapScale?: number;
  }
>;

function RippleButton(props: RippleButtonProps) {
  return (
    <ReducedMotionConfig>
      <RippleButtonContent {...props} />
    </ReducedMotionConfig>
  );
}

function RippleButtonContent({
  ref,
  onClick,
  hoverScale = 1,
  tapScale = TAP_SCALE,
  asChild = false,
  transition,
  style,
  ...props
}: RippleButtonProps) {
  const { tempo } = useMotionTokens();
  const defaultTransition = useTempoTransition(SCALE_SPRING);
  const [ripples, setRipples] = React.useState<Ripple[]>([]);
  const buttonRef = React.useRef<HTMLButtonElement>(null);
  const nextIdRef = React.useRef(0);
  const timersRef = React.useRef(new Set<ReturnType<typeof setTimeout>>());
  const reduce = useShouldReduceMotion();
  React.useImperativeHandle(ref, () => buttonRef.current as HTMLButtonElement);

  const createRipple = React.useCallback(
    (event: React.MouseEvent<HTMLButtonElement>) => {
      const button = buttonRef.current;
      if (!button) return;

      const rect = button.getBoundingClientRect();
      const x = (event.clientX - rect.left) * (button.offsetWidth / rect.width);
      const y =
        (event.clientY - rect.top) * (button.offsetHeight / rect.height);

      const newRipple: Ripple = {
        id: nextIdRef.current++,
        x,
        y,
      };

      setRipples((prev) => [...prev, newRipple]);

      const timer = setTimeout(() => {
        timersRef.current.delete(timer);
        setRipples((prev) => prev.filter((r) => r.id !== newRipple.id));
      }, 600 * tempo);
      timersRef.current.add(timer);
    },
    [tempo],
  );

  React.useEffect(() => {
    const pending = timersRef.current;
    return () => pending.forEach((timer) => clearTimeout(timer));
  }, []);

  const handleClick = React.useCallback(
    (event: React.MouseEvent<HTMLButtonElement>) => {
      createRipple(event);
      if (onClick) {
        onClick(event);
      }
    },
    [createRipple, onClick],
  );

  const Component = asChild ? Slot : motion.button;

  return (
    <RippleButtonProvider value={{ ripples, setRipples }}>
      <Component
        ref={buttonRef}
        data-slot="ripple-button"
        onClick={handleClick}
        initial={reduce ? undefined : { transform: 'scale(1)' }}
        whileTap={reduce ? undefined : { transform: `scale(${tapScale})` }}
        whileHover={
          reduce || hoverScale === 1
            ? undefined
            : { transform: `scale(${hoverScale})` }
        }
        transition={transition ?? defaultTransition}
        style={{
          position: 'relative',
          overflow: 'hidden',
          ...style,
        }}
        {...props}
      />
    </RippleButtonProvider>
  );
}

type RippleButtonRipplesProps = WithAsChild<
  HTMLMotionProps<'span'> & {
    color?: string;
    scale?: number;
  }
>;

function RippleButtonRipples({
  color = 'var(--ripple-button-ripple-color)',
  scale = 10,
  transition,
  asChild = false,
  style,
  ...props
}: RippleButtonRipplesProps) {
  const { ripples } = useRippleButton();
  const defaultTransition = useTempoTransition(RIPPLE_TRANSITION);
  const reduce = useShouldReduceMotion();

  const Component = asChild ? Slot : motion.span;

  return ripples.map((ripple) => (
    <Component
      key={ripple.id}
      initial={{ scale: reduce ? scale : 0, opacity: 0.5 }}
      animate={{ scale, opacity: 0 }}
      transition={transition ?? defaultTransition}
      style={{
        position: 'absolute',
        borderRadius: '50%',
        pointerEvents: 'none',
        width: '20px',
        height: '20px',
        backgroundColor: color,
        top: ripple.y - 10,
        left: ripple.x - 10,
        ...style,
      }}
      {...props}
    />
  ));
}

export {
  RippleButton,
  RippleButtonRipples,
  type RippleButtonProps,
  type RippleButtonRipplesProps,
};

'use client';

import * as React from 'react';

import { ReducedMotionConfig, useShouldReduceMotion } from '../../utils/motion';
import {
  useIsInView,
  type UseIsInViewOptions,
} from '../../utils/use-is-in-view';

type CodeBlockProps = React.ComponentProps<'div'> & {
  code: string;
  lang: string;
  theme?: 'light' | 'dark';
  themes?: { light: string; dark: string };
  writing?: boolean;
  duration?: number;
  delay?: number;
  onDone?: () => void;
  onWrite?: (info: { index: number; length: number; done: boolean }) => void;
  scrollContainerRef?: React.RefObject<HTMLElement | null>;
} & UseIsInViewOptions;

const DEFAULT_THEMES = { light: 'github-light', dark: 'github-dark' };

function CodeBlock(props: CodeBlockProps) {
  return (
    <ReducedMotionConfig>
      <CodeBlockContent {...props} />
    </ReducedMotionConfig>
  );
}

function CodeBlockContent({
  ref,
  code,
  lang,
  theme = 'light',
  themes = DEFAULT_THEMES,
  writing = false,
  duration = 5000,
  delay = 0,
  onDone,
  onWrite,
  scrollContainerRef,
  inView = false,
  inViewOnce = true,
  inViewMargin = '0px',
  ...props
}: CodeBlockProps) {
  const { ref: localRef, isInView } = useIsInView(
    ref as React.Ref<HTMLDivElement>,
    {
      inView,
      inViewOnce,
      inViewMargin,
    },
  );
  const reduce = useShouldReduceMotion();
  const animated = writing && !reduce;

  const [visibleCode, setVisibleCode] = React.useState('');
  const [highlightedCode, setHighlightedCode] = React.useState('');
  const [isDone, setIsDone] = React.useState(false);

  const onDoneRef = React.useRef(onDone);
  const doneCodeRef = React.useRef<string | null>(null);
  const onWriteRef = React.useRef(onWrite);
  React.useLayoutEffect(() => {
    onDoneRef.current = onDone;
    onWriteRef.current = onWrite;
  });

  const lightTheme = themes.light;
  const darkTheme = themes.dark;

  React.useEffect(() => {
    if (!visibleCode.length || !isInView) return;
    let cancelled = false;

    const loadHighlightedCode = async () => {
      try {
        const { codeToHtml } = await import('shiki');

        const highlighted = await codeToHtml(visibleCode, {
          lang,
          themes: { light: lightTheme, dark: darkTheme },
          defaultColor: theme,
        });

        if (!cancelled) setHighlightedCode(highlighted);
      } catch (e) {
        console.error(`Language "${lang}" could not be loaded.`, e);
      }
    };

    loadHighlightedCode();
    return () => {
      cancelled = true;
    };
  }, [lang, lightTheme, darkTheme, isInView, visibleCode, theme]);

  React.useEffect(() => {
    if (!animated) {
      if (doneCodeRef.current === code) return;
      doneCodeRef.current = code;
      setVisibleCode(code);
      setIsDone(true);
      onDoneRef.current?.();
      onWriteRef.current?.({
        index: code.length,
        length: code.length,
        done: true,
      });
      return;
    }

    if (!code.length || !isInView) return;

    doneCodeRef.current = null;
    setVisibleCode('');
    setIsDone(false);

    const characters = Array.from(code);
    let index = 0;
    const interval = duration / characters.length;
    let intervalId: ReturnType<typeof setInterval> | undefined;

    const timeout = setTimeout(() => {
      intervalId = setInterval(() => {
        if (index < characters.length) {
          index += 1;
          setVisibleCode(characters.slice(0, index).join(''));
          onWriteRef.current?.({
            index,
            length: characters.length,
            done: false,
          });
          localRef.current?.scrollTo({
            top: localRef.current?.scrollHeight,
            behavior: 'smooth',
          });
        } else {
          clearInterval(intervalId);
          setIsDone(true);
          onDoneRef.current?.();
          onWriteRef.current?.({
            index: characters.length,
            length: characters.length,
            done: true,
          });
        }
      }, interval);
    }, delay);

    return () => {
      clearTimeout(timeout);
      clearInterval(intervalId);
    };
  }, [code, duration, delay, isInView, animated, localRef]);

  React.useEffect(() => {
    if (!animated || !isInView) return;
    const el =
      scrollContainerRef?.current ??
      (localRef.current?.parentElement as HTMLElement | null) ??
      (localRef.current as unknown as HTMLElement | null);

    if (!el) return;

    const frame = requestAnimationFrame(() => {
      el.scrollTo({
        top: el.scrollHeight,
        behavior: 'smooth',
      });
    });
    return () => cancelAnimationFrame(frame);
  }, [highlightedCode, animated, isInView, scrollContainerRef, localRef]);

  return (
    <div
      ref={localRef}
      data-slot="code-block"
      data-writing={writing}
      data-done={isDone}
      dangerouslySetInnerHTML={{ __html: highlightedCode }}
      {...props}
    />
  );
}

export { CodeBlock, type CodeBlockProps };

'use client';

import * as React from 'react';
import {
  motion,
  useMotionValue,
  useSpring,
  useTransform,
  AnimatePresence,
  cancelFrame,
  frame,
  type HTMLMotionProps,
  type MotionValue,
  type SpringOptions,
  type Transition,
} from 'motion/react';

import { getStrictContext } from '../../utils/strict-context';
import {
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../utils/motion';
import { Slot, type WithAsChild } from '../slot';

const OPACITY_TRANSITION: Transition = {
  duration: 0.3,
  ease: [0.25, 0.1, 0.35, 1],
};
const ENTER_TRANSITION: Transition = {
  scale: { type: 'spring', stiffness: 550, damping: 30, restSpeed: 10 },
  opacity: OPACITY_TRANSITION,
};
const EXIT_TRANSITION: Transition = {
  scale: {
    type: 'spring',
    stiffness: 550,
    damping: 2 * Math.sqrt(550),
    restSpeed: 10,
  },
  opacity: OPACITY_TRANSITION,
};
const FOLLOW_SPRING: SpringOptions = { stiffness: 500, damping: 50, bounce: 0 };

type CursorContextType = {
  cursorPos: { x: number; y: number };
  cursorX: MotionValue<number>;
  cursorY: MotionValue<number>;
  active: boolean;
  global: boolean;
  containerRef: React.RefObject<HTMLDivElement | null>;
  cursorRef: React.RefObject<HTMLDivElement | null>;
};

const [LocalCursorProvider, useCursor] =
  getStrictContext<CursorContextType>('CursorContext');

type CursorProviderProps = {
  children: React.ReactNode;
  global?: boolean;
};

function CursorProvider({ children, global = false }: CursorProviderProps) {
  const cursorX = useMotionValue(0);
  const cursorY = useMotionValue(0);
  const [activeState, setActiveState] = React.useState(false);
  const active = activeState;
  const activeRef = React.useRef(false);

  const setActive = React.useCallback((next: boolean) => {
    if (activeRef.current === next) return;
    activeRef.current = next;
    setActiveState(next);
  }, []);

  const containerRef = React.useRef<HTMLDivElement>(null);
  const cursorRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const id = '__cursor_none_style__';
    if (document.getElementById(id)) return;

    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      .animate-ui-cursor-none, .animate-ui-cursor-none * { cursor: none !important; }
    `;
    document.head.appendChild(style);
  }, []);

  React.useEffect(() => {
    let removeListeners: () => void;

    if (global) {
      const handlePointerMove = (e: PointerEvent) => {
        if (e.pointerType === 'touch') return;
        cursorX.set(e.clientX);
        cursorY.set(e.clientY);
        setActive(true);
      };

      const handlePointerOut = (e: PointerEvent | MouseEvent) => {
        if (e instanceof PointerEvent && e.relatedTarget === null) {
          setActive(false);
        }
      };

      const handleVisibilityChange = () => {
        if (document.visibilityState === 'hidden') setActive(false);
      };

      window.addEventListener('pointermove', handlePointerMove, {
        passive: true,
      });
      window.addEventListener('pointerout', handlePointerOut, {
        passive: true,
      });
      window.addEventListener('mouseout', handlePointerOut, { passive: true });
      document.addEventListener('visibilitychange', handleVisibilityChange);

      removeListeners = () => {
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerout', handlePointerOut);
        window.removeEventListener('mouseout', handlePointerOut);
        document.removeEventListener(
          'visibilitychange',
          handleVisibilityChange,
        );
      };
    } else {
      if (!containerRef.current) return;

      const parent = containerRef.current.parentElement;
      if (!parent) return;

      if (getComputedStyle(parent).position === 'static') {
        parent.style.position = 'relative';
      }

      const handlePointerMove = (e: PointerEvent) => {
        if (e.pointerType === 'touch') return;
        const rect = parent.getBoundingClientRect();
        cursorX.set(e.clientX - rect.left);
        cursorY.set(e.clientY - rect.top);
        setActive(true);
      };

      const handlePointerOut = (e: PointerEvent | MouseEvent) => {
        if (
          e.relatedTarget === null ||
          !(parent as Node).contains(e.relatedTarget as Node)
        ) {
          setActive(false);
        }
      };

      parent.addEventListener('pointermove', handlePointerMove, {
        passive: true,
      });
      parent.addEventListener('pointerout', handlePointerOut, {
        passive: true,
      });
      parent.addEventListener('mouseout', handlePointerOut, { passive: true });

      removeListeners = () => {
        parent.removeEventListener('pointermove', handlePointerMove);
        parent.removeEventListener('pointerout', handlePointerOut);
        parent.removeEventListener('mouseout', handlePointerOut);
      };
    }

    return removeListeners;
  }, [global, cursorX, cursorY, setActive]);

  const value = React.useMemo<CursorContextType>(
    () => ({
      get cursorPos() {
        return { x: cursorX.get(), y: cursorY.get() };
      },
      cursorX,
      cursorY,
      active,
      global,
      containerRef,
      cursorRef,
    }),
    [cursorX, cursorY, active, global],
  );

  return (
    <LocalCursorProvider value={value}>
      <ReducedMotionConfig>{children}</ReducedMotionConfig>
    </LocalCursorProvider>
  );
}

type CursorContainerProps = WithAsChild<HTMLMotionProps<'div'>>;

function CursorContainer({
  ref,
  asChild = false,
  ...props
}: CursorContainerProps) {
  const { containerRef, global, active } = useCursor();
  React.useImperativeHandle(ref, () => containerRef.current as HTMLDivElement);

  const Component = asChild ? Slot : motion.div;

  return (
    <Component
      ref={containerRef}
      data-slot="cursor-container"
      data-global={global}
      data-active={active}
      {...props}
    />
  );
}

type CursorProps = WithAsChild<
  HTMLMotionProps<'div'> & {
    children: React.ReactNode;
  }
>;

function Cursor({
  ref,
  asChild = false,
  style,
  transition,
  ...props
}: CursorProps) {
  const { cursorX, cursorY, active, containerRef, cursorRef, global } =
    useCursor();
  React.useImperativeHandle(ref, () => cursorRef.current as HTMLDivElement);

  const enterTransition = useTempoTransition(ENTER_TRANSITION);
  const exitTransition = useTempoTransition(EXIT_TRANSITION);

  const positionX = useTransform(cursorX, (value) => value);
  const positionY = useTransform(cursorY, (value) => value);

  React.useEffect(() => {
    const target = global
      ? document.documentElement
      : containerRef.current?.parentElement;

    if (!target) return;

    if (active) {
      target.classList.add('animate-ui-cursor-none');
    } else {
      target.classList.remove('animate-ui-cursor-none');
    }

    return () => {
      target.classList.remove('animate-ui-cursor-none');
    };
  }, [active, global, containerRef]);

  const Component = asChild ? Slot : motion.div;

  return (
    <AnimatePresence>
      {active && (
        <Component
          ref={cursorRef}
          data-slot="cursor"
          data-global={global}
          data-active={active}
          style={{
            pointerEvents: 'none',
            zIndex: 9999,
            position: global ? 'fixed' : 'absolute',
            top: 0,
            left: 0,
            x: positionX,
            y: positionY,
            ...style,
          }}
          initial={{ scale: 0, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{
            scale: 0,
            opacity: 0,
            ...(transition ? {} : { transition: exitTransition }),
          }}
          transition={transition ?? enterTransition}
          {...props}
        />
      )}
    </AnimatePresence>
  );
}

type CursorFollowSide = 'top' | 'right' | 'bottom' | 'left';
type CursorFollowAlign = 'start' | 'center' | 'end';

type CursorFollowProps = WithAsChild<
  Omit<HTMLMotionProps<'div'>, 'transition'> & {
    side?: CursorFollowSide;
    sideOffset?: number;
    align?: CursorFollowAlign;
    alignOffset?: number;
    transition?: SpringOptions;
    children: React.ReactNode;
  }
>;

function CursorFollow({
  ref,
  asChild = false,
  side = 'bottom',
  sideOffset = 0,
  align = 'end',
  alignOffset = 0,
  style,
  transition: transitionProp,
  ...props
}: CursorFollowProps) {
  const defaultTransition = useTempoTransition(FOLLOW_SPRING);
  const transition = transitionProp ?? defaultTransition;
  const enterTransition = useTempoTransition(ENTER_TRANSITION);
  const exitTransition = useTempoTransition(EXIT_TRANSITION);
  const { cursorX, cursorY, active, cursorRef, global } = useCursor();
  const reduce = useShouldReduceMotion();
  const cursorFollowRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(
    ref,
    () => cursorFollowRef.current as HTMLDivElement,
  );

  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const springX = useSpring(x, transition);
  const springY = useSpring(y, transition);
  const positionX = useTransform(() => (reduce ? x : springX).get());
  const positionY = useTransform(() => (reduce ? y : springY).get());

  const calculateOffset = React.useCallback(() => {
    const rect = cursorFollowRef.current?.getBoundingClientRect();
    const width = rect?.width ?? 0;
    const height = rect?.height ?? 0;

    let offsetX = 0;
    let offsetY = 0;

    switch (side) {
      case 'top':
        offsetY = height + sideOffset;
        switch (align) {
          case 'start':
            offsetX = width + alignOffset;
            break;
          case 'center':
            offsetX = width / 2;
            break;
          case 'end':
            offsetX = -alignOffset;
            break;
        }
        break;

      case 'bottom':
        offsetY = -sideOffset;
        switch (align) {
          case 'start':
            offsetX = width + alignOffset;
            break;
          case 'center':
            offsetX = width / 2;
            break;
          case 'end':
            offsetX = -alignOffset;
            break;
        }
        break;

      case 'left':
        offsetX = width + sideOffset;
        switch (align) {
          case 'start':
            offsetY = height + alignOffset;
            break;
          case 'center':
            offsetY = height / 2;
            break;
          case 'end':
            offsetY = -alignOffset;
            break;
        }
        break;

      case 'right':
        offsetX = -sideOffset;
        switch (align) {
          case 'start':
            offsetY = height + alignOffset;
            break;
          case 'center':
            offsetY = height / 2;
            break;
          case 'end':
            offsetY = -alignOffset;
            break;
        }
        break;
    }

    return { x: offsetX, y: offsetY };
  }, [side, align, sideOffset, alignOffset]);

  const update = React.useCallback(() => {
    const offset = calculateOffset();
    const cursorRect = cursorRef.current?.getBoundingClientRect();
    const cursorWidth = cursorRect?.width ?? 20;
    const cursorHeight = cursorRect?.height ?? 20;

    x.set(cursorX.get() - offset.x + cursorWidth / 2);
    y.set(cursorY.get() - offset.y + cursorHeight / 2);
  }, [calculateOffset, cursorRef, cursorX, cursorY, x, y]);

  React.useEffect(() => {
    update();
  }, [update]);

  React.useEffect(() => {
    if (!active) return;
    frame.postRender(update);
    const unsubscribeX = cursorX.on('change', update);
    const unsubscribeY = cursorY.on('change', update);

    return () => {
      cancelFrame(update);
      unsubscribeX();
      unsubscribeY();
    };
  }, [active, update, cursorX, cursorY]);

  const Component = asChild ? Slot : motion.div;

  return (
    <AnimatePresence>
      {active && (
        <Component
          ref={cursorFollowRef}
          data-slot="cursor-follow"
          data-global={global}
          data-active={active}
          style={{
            pointerEvents: 'none',
            zIndex: 9998,
            position: global ? 'fixed' : 'absolute',
            top: 0,
            left: 0,
            x: positionX,
            y: positionY,
            ...style,
          }}
          initial={{ scale: 0, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0, opacity: 0, transition: exitTransition }}
          transition={enterTransition}
          {...props}
        />
      )}
    </AnimatePresence>
  );
}

