      {Array.from({ length: count }).map((_, i) => {
        const angle = i * angleStep;
        const x = Math.cos(angle) * radius;
        const y = Math.sin(angle) * radius;

        return (
          <motion.circle
            key={i}
            cx={cx}
            cy={cy}
            r={r0}
            fill={item.color}
            initial={{ scale: 0, opacity: 0 }}
            animate={{
              cx: cx + x,
              cy: cy + y,
              scale: [0, 1, 0],
              opacity: [0, 1, 0],
            }}
            transition={{
              duration: d,
              delay: i * (d * 0.08),
              ease: 'easeOut',
            }}
          />
        );
      })}
    </motion.svg>
