'use client';

import * as React from 'react';
import {
  animate,
  cancelFrame,
  frame,
  useMotionValue,
  type MotionValue,
  type Transition,
} from 'motion/react';

import { mergeRefs } from '../../../internal/anchored';
import { screenScale } from '../../../internal/screen-scale';
import {
  motionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';

const SETTLE = motionTokens.transition.fade;

type ScrollFadeOrientation = 'vertical' | 'horizontal' | 'both';

type ScrollFadeEdge = 'top' | 'bottom' | 'left' | 'right';

type UseScrollFadeOptions = {
  orientation?: ScrollFadeOrientation;
  size?: number;
  shrink?: number;
  blur?: number;
  transition?: Transition;
  enabled?: boolean;
};

type ScrollFadeValues = Record<ScrollFadeEdge, MotionValue<number>>;

const EDGES: ScrollFadeEdge[] = ['top', 'bottom', 'left', 'right'];

const VAR = {
  top: '--scroll-fade-top',
  bottom: '--scroll-fade-bottom',
  left: '--scroll-fade-left',
  right: '--scroll-fade-right',
  size: '--scroll-fade-size',
} as const;

const edgeStop = (edge: ScrollFadeEdge) =>
  `rgb(0 0 0 / calc(1 - var(${VAR[edge]}, 0)))`;
const depth = (edge: ScrollFadeEdge) =>
  `calc(var(${VAR.size}) * min(1, var(${VAR[edge]}, 0) * 1000))`;

const GRADIENT_Y = `linear-gradient(to bottom, ${edgeStop('top')} 0, #000 ${depth('top')}, #000 calc(100% - ${depth('bottom')}), ${edgeStop('bottom')} 100%)`;
const GRADIENT_X = `linear-gradient(to right, ${edgeStop('left')} 0, #000 ${depth('left')}, #000 calc(100% - ${depth('right')}), ${edgeStop('right')} 100%)`;

const MASKS: Record<ScrollFadeOrientation, string> = {
  vertical: GRADIENT_Y,
  horizontal: GRADIENT_X,
  both: `${GRADIENT_Y}, ${GRADIENT_X}`,
};

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));
const smooth = (value: number) => value * value * (3 - 2 * value);

const ZONE = 1.75;
const GESTURE_GAP = 150;

type ItemSlot = { item: HTMLElement; x: number; y: number; ownFilter: boolean };

const GROUP = 'ul, ol, [role="list"], [role="group"]';

function collectItems(parent: Element, items: HTMLElement[]) {
  for (const child of parent.children) {
    if (!(child instanceof HTMLElement)) continue;
    const isGroup =
      child.matches(GROUP) ||
      Array.from(child.children).some((inner) => inner.matches(GROUP));
    if (isGroup) collectItems(child, items);
    else items.push(child);
  }
  return items;
}

function itemsOf(el: HTMLElement) {
  let parent: Element = el;
  while (parent.children.length === 1) parent = parent.children[0]!;
  return collectItems(parent, []);
}

function setMask(el: HTMLElement, mask: string | null) {
  const style = el.style;
  if (mask) {
    style.setProperty('mask-image', mask);
    style.setProperty('-webkit-mask-image', mask);
    style.setProperty('mask-composite', 'intersect');
    style.setProperty('-webkit-mask-composite', 'source-in');
  } else {
    for (const property of [
      'mask-image',
      '-webkit-mask-image',
      'mask-composite',
      '-webkit-mask-composite',
    ])
      style.removeProperty(property);
  }
}

function useScrollFade(
  ref: React.RefObject<HTMLElement | null>,
  {
    orientation = 'vertical',
    size = 40,
    shrink = 0.03,
    blur = 4,
    transition: transitionProp,
    enabled = true,
  }: UseScrollFadeOptions = {},
): ScrollFadeValues {
  const reduce = useShouldReduceMotion();
  const settle = useTempoTransition(transitionProp ?? SETTLE);
  const settleRef = React.useRef(settle);
  React.useEffect(() => {
    settleRef.current = settle;
  });

  const top = useMotionValue(0);
  const bottom = useMotionValue(0);
  const left = useMotionValue(0);
  const right = useMotionValue(0);
  const values = React.useMemo(
    () => ({ top, bottom, left, right }),
    [top, bottom, left, right],
  );

  const reduceRef = React.useRef(reduce);
  React.useEffect(() => {
    reduceRef.current = reduce;
  }, [reduce]);

  React.useEffect(() => {
    const el = ref.current;
    if (!el || !enabled) return;

    const vertical = orientation !== 'horizontal';
    const horizontal = orientation !== 'vertical';
    const mask = MASKS[orientation];
    let masked = false;

    el.style.setProperty(VAR.size, `${size}px`);

    const shrunk = new Set<HTMLElement>();
    const blurred = new Set<HTMLElement>();
    const restore = () => {
      for (const item of shrunk) item.style.removeProperty('scale');
      for (const item of blurred) item.style.removeProperty('filter');
      shrunk.clear();
      blurred.clear();
    };

    let slots: ItemSlot[] = [];
    let width = 0;
    let height = 0;
    const measureItems = () => {
      if (!shrink && !blur) {
        slots = [];
        return;
      }
      const box = el.getBoundingClientRect();
      const [sx, sy] = screenScale(el);
      width = el.clientWidth;
      height = el.clientHeight;
      slots = itemsOf(el).map((item) => {
        const rect = item.getBoundingClientRect();
        return {
          item,
          x: (rect.left + rect.width / 2 - box.left) / sx + el.scrollLeft,
          y: (rect.top + rect.height / 2 - box.top) / sy + el.scrollTop,
          ownFilter:
            !blurred.has(item) && getComputedStyle(item).filter !== 'none',
        };
      });
    };

    const zone = size * ZONE;
    const reach = (distance: number) =>
      zone > 0 ? smooth(clamp01(1 - distance / zone)) : 0;

    let dirty = true;
    const paintItems = () => {
      if (dirty) {
        dirty = false;
        measureItems();
      }
      const scale = reduceRef.current ? 0 : shrink;
      if (!slots.length || (!scale && !blur)) return restore();
      const scrollX = el.scrollLeft;
      const scrollY = el.scrollTop;
      for (const { item, x, y, ownFilter } of slots) {
        let depth = 0;
        if (vertical) {
          const center = y - scrollY;
          depth = Math.max(
            reach(center) * values.top.get(),
            reach(height - center) * values.bottom.get(),
          );
        }
        if (horizontal) {
          const center = x - scrollX;
          depth = Math.max(
            depth,
            reach(center) * values.left.get(),
            reach(width - center) * values.right.get(),
          );
        }
        if (depth > 0.001 && scale) {
          item.style.scale = String(1 - scale * depth);
          shrunk.add(item);
        } else if (shrunk.delete(item)) item.style.removeProperty('scale');
        if (depth > 0.001 && blur && !ownFilter) {
          item.style.filter = `blur(${(blur * depth).toFixed(2)}px)`;
          blurred.add(item);
        } else if (blurred.delete(item)) item.style.removeProperty('filter');
      }
    };

    let scheduled = false;
    const runPaint = () => {
      scheduled = false;
      paintItems();
    };
    const shrinkItems = () => {
      if (scheduled) return;
      scheduled = true;
      frame.render(runPaint);
    };

    const write = () => {
      let any = false;
      for (const edge of EDGES) {
        const amount = clamp01(values[edge].get());
        if (amount > 0.001) any = true;
        el.style.setProperty(VAR[edge], amount.toFixed(4));
      }
      if (any !== masked) {
        masked = any;
        setMask(el, any ? mask : null);
      }
      shrinkItems();
    };

    const unsubscribe = EDGES.map((edge) => values[edge].on('change', write));

    const ramp = size / 2;
    const amount = (distance: number) =>
      ramp > 0 ? clamp01(distance / ramp) : distance > 0.5 ? 1 : 0;

    const measure = (follow: boolean) => {
      const targets: Record<ScrollFadeEdge, number> = {
        top: 0,
        bottom: 0,
        left: 0,
        right: 0,
      };

      if (vertical) {
        const max = el.scrollHeight - el.clientHeight;
        if (max > 1) {
          targets.top = amount(el.scrollTop);
          targets.bottom = amount(max - el.scrollTop);
        }
      }

      if (horizontal) {
        const max = el.scrollWidth - el.clientWidth;
        if (max > 1) {
          const fromStart = Math.abs(el.scrollLeft);
          const fromEnd = max - fromStart;
          const rtl = getComputedStyle(el).direction === 'rtl';
          targets.left = amount(rtl ? fromEnd : fromStart);
          targets.right = amount(rtl ? fromStart : fromEnd);
        }
      }

      for (const edge of EDGES) {
        if (follow || reduceRef.current) values[edge].jump(targets[edge]);
        else if (Math.abs(values[edge].get() - targets[edge]) > 0.001)
          animate(values[edge], targets[edge], settleRef.current);
      }
      write();
    };

    measure(true);

    let lastScroll = 0;
    const onScroll = () => {
      const now = performance.now();
      if (now - lastScroll > GESTURE_GAP) dirty = true;
      lastScroll = now;
      measure(true);
    };
    el.addEventListener('scroll', onScroll, { passive: true });

    const resizeObserver = new ResizeObserver(() => {
      dirty = true;
      measure(false);
    });
    const observeChildren = () => {
      resizeObserver.disconnect();
      resizeObserver.observe(el);
      for (const child of el.children) resizeObserver.observe(child);
    };
    observeChildren();
    const mutationObserver = new MutationObserver((records) => {
      if (records.some((record) => record.target === el)) observeChildren();
      dirty = true;
      measure(false);
    });
    mutationObserver.observe(el, { childList: true, subtree: true });

    return () => {
      el.removeEventListener('scroll', onScroll);
      cancelFrame(runPaint);
      resizeObserver.disconnect();
      mutationObserver.disconnect();
      unsubscribe.forEach((off) => off());
      setMask(el, null);
      restore();
      for (const name of Object.values(VAR)) el.style.removeProperty(name);
      for (const edge of EDGES) values[edge].jump(0);
    };
  }, [ref, enabled, orientation, size, shrink, blur, values]);

  return values;
}

type ScrollFadeProps = React.ComponentProps<'div'> &
  UseScrollFadeOptions & {
    asChild?: boolean;
  };

type ChildProps = React.HTMLAttributes<HTMLElement> & {
  ref?: React.Ref<HTMLElement | null>;
};

const OVERFLOW: Record<ScrollFadeOrientation, React.CSSProperties> = {
  vertical: { overflowY: 'auto' },
  horizontal: { overflowX: 'auto' },
  both: { overflow: 'auto' },
};

function ScrollFade({
  ref,
  asChild = false,
  orientation = 'vertical',
  size,
  shrink,
  blur,
  transition,
  enabled,
  style,
  children,
  ...props
}: ScrollFadeProps) {
  const localRef = React.useRef<HTMLDivElement | null>(null);
  const ownRef = React.isValidElement<ChildProps>(children)
    ? children.props.ref
    : undefined;
  const childRef = React.useMemo(
    () => mergeRefs<HTMLElement | null>(localRef, ownRef),
    [ownRef],
  );
  React.useImperativeHandle(ref, () => localRef.current as HTMLDivElement);

  useScrollFade(localRef, {
    orientation,
    size,
    shrink,
    blur,
    transition,
    enabled,
  });

  const sharedProps = {
    'data-slot': 'scroll-fade',
    'data-orientation': orientation,
    ...props,
  };

  if (asChild && React.isValidElement<ChildProps>(children)) {
    const child = children;
    return React.cloneElement(child, {
      ...child.props,
      ...sharedProps,
      className:
        [child.props.className, props.className].filter(Boolean).join(' ') ||
        undefined,
      style: { ...OVERFLOW[orientation], ...child.props.style, ...style },
      ref: childRef,
    });
  }

  return (
    <div
      ref={localRef}
      style={{ ...OVERFLOW[orientation], ...style }}
      {...sharedProps}
    >
      {children}
    </div>
  );
}

export {
  ScrollFade,
  useScrollFade,
  type ScrollFadeProps,
  type ScrollFadeOrientation,
  type ScrollFadeValues,
  type UseScrollFadeOptions,
};

'use client';

import * as React from 'react';
import { motion } from 'motion/react';

import {
  ReducedMotionConfig,
  useShouldReduceMotion,
} from '../../../utils/motion';

type ShineProps = React.ComponentProps<'div'> & {
  color?: string;
  opacity?: number;
  delay?: number;
  duration?: number;
  loop?: boolean;
  loopDelay?: number;
  deg?: number;
  enable?: boolean;
  enableOnHover?: boolean;
  enableOnTap?: boolean;
  asChild?: boolean;
  children?: React.ReactNode;
};

function Shine(props: ShineProps) {
  return (
    <ReducedMotionConfig>
      <ShineInner {...props} />
    </ReducedMotionConfig>
  );
}

const ShineInner = ({
  color = 'currentColor',
  opacity = 0.3,
  delay = 0,
  duration = 1200,
  loop = false,
  loopDelay = 0,
  deg = -15,
  enable: enableProp = true,
  enableOnHover = false,
  enableOnTap = false,
  asChild = false,
  style,
  children,
  onMouseEnter,
  onMouseLeave,
  onPointerDown,
  ...props
}: ShineProps) => {
  const reduce = useShouldReduceMotion();
  const enable = enableProp && !reduce;
  const isAlwaysOn = enable && !enableOnHover && !enableOnTap;
  const [animateState, setAnimateState] = React.useState<'initial' | 'shine'>(
    isAlwaysOn ? 'shine' : 'initial',
  );
  const hoverLoopTimeoutRef = React.useRef<number | undefined>(undefined);
  const hoverLoopRafRef = React.useRef<number | undefined>(undefined);
  const [isHovered, setIsHovered] = React.useState(false);
  const [currentDelay, setCurrentDelay] = React.useState(delay);

  React.useEffect(() => {
    setAnimateState(isAlwaysOn ? 'shine' : 'initial');
    if (isAlwaysOn) {
      setCurrentDelay(delay);
    }
  }, [isAlwaysOn, delay]);

  React.useEffect(() => {
    return () => {
      if (hoverLoopTimeoutRef.current !== undefined) {
        window.clearTimeout(hoverLoopTimeoutRef.current);
      }
      if (hoverLoopRafRef.current !== undefined) {
        window.cancelAnimationFrame(hoverLoopRafRef.current);
      }
    };
  }, []);

  const handlePointerDown = React.useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      onPointerDown?.(e);
      if (!enable || !enableOnTap || isAlwaysOn) return;
      setCurrentDelay(delay);
      setAnimateState('shine');
    },
    [enable, enableOnTap, isAlwaysOn, delay, onPointerDown],
  );

  const handleMouseEnter = React.useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      onMouseEnter?.(e);
      if (!enable || !enableOnHover || isAlwaysOn) return;
      setIsHovered(true);
      setCurrentDelay(delay);
      setAnimateState('shine');
    },
    [enable, enableOnHover, isAlwaysOn, delay, onMouseEnter],
  );

  const handleMouseLeave = React.useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      onMouseLeave?.(e);
      if (!enable || !enableOnHover || isAlwaysOn) return;
      setIsHovered(false);
      if (hoverLoopTimeoutRef.current !== undefined) {
        window.clearTimeout(hoverLoopTimeoutRef.current);
        hoverLoopTimeoutRef.current = undefined;
      }
      if (hoverLoopRafRef.current !== undefined) {
        window.cancelAnimationFrame(hoverLoopRafRef.current);
        hoverLoopRafRef.current = undefined;
      }
    },
    [enable, enableOnHover, isAlwaysOn, onMouseLeave],
  );

  const scheduleNextShine = React.useCallback((delayMs: number) => {
    if (hoverLoopTimeoutRef.current !== undefined) {
      window.clearTimeout(hoverLoopTimeoutRef.current);
      hoverLoopTimeoutRef.current = undefined;
    }
    if (hoverLoopRafRef.current !== undefined) {
      window.cancelAnimationFrame(hoverLoopRafRef.current);
      hoverLoopRafRef.current = undefined;
    }
    if (delayMs > 0) {
      hoverLoopTimeoutRef.current = window.setTimeout(() => {
        setAnimateState('shine');
        hoverLoopTimeoutRef.current = undefined;
      }, delayMs);
    } else {
      hoverLoopRafRef.current = window.requestAnimationFrame(() => {
        hoverLoopRafRef.current = window.requestAnimationFrame(() => {
          setAnimateState('shine');
          hoverLoopRafRef.current = undefined;
        });
      });
    }
  }, []);

  const handleAnimationComplete = React.useCallback(() => {
    if (animateState !== 'shine') return;
    if (isAlwaysOn) {
      if (loop) {
        setAnimateState('initial');
        setCurrentDelay(0);
        scheduleNextShine(loopDelay);
      }
      return;
    }

    if (enableOnHover) {
      if (isHovered) {
        if (loop) {
          setAnimateState('initial');
          setCurrentDelay(0);
          scheduleNextShine(loopDelay);
        } else {
          setAnimateState('initial');
        }
      } else {
        setAnimateState('initial');
      }
      return;
    }

    if (enableOnTap) {
      setAnimateState('initial');
    }
  }, [
    animateState,
    isAlwaysOn,
    loop,
    enableOnHover,
    isHovered,
    enableOnTap,
    scheduleNextShine,
    loopDelay,
  ]);

  const overlayElement = (
    <motion.div
      initial="initial"
      animate={animateState}
      variants={{
        initial: { x: '-100%', skewX: deg, transition: { duration: 0 } },
        shine: { x: '100%', skewX: deg },
      }}
      transition={{
        duration: duration / 1000,
        ease: [0.4, 0, 0.2, 1],
        delay: currentDelay / 1000,
      }}
      style={{
        position: 'absolute',
        inset: 0,
        zIndex: 10,
        pointerEvents: 'none',
        width: '100%',
        height: '100%',
        willChange: 'transform, opacity',
        background: `linear-gradient(to right, transparent, ${color}, transparent)`,
        opacity,
      }}
      onAnimationComplete={handleAnimationComplete}
    />
  );

  if (asChild) {
    if (!React.isValidElement(children)) {
      return null;
    }

    const child = children as React.ReactElement<Record<string, unknown>>;
    const childProps = (child.props ?? {}) as Record<string, unknown> & {
      className?: string;
      style?: React.CSSProperties;
      onMouseEnter?: (e: React.MouseEvent) => void;
      onMouseLeave?: (e: React.MouseEvent) => void;
      onPointerDown?: (e: React.PointerEvent) => void;
      children?: React.ReactNode;
    };

    const mergedClassName = [
      childProps.className,
      (props as { className?: string }).className,
    ]
      .filter(Boolean)
      .join(' ');
    const mergedStyle = {
      ...(childProps.style || {}),
      ...(style || {}),
      position: 'relative',
      overflow: 'hidden',
    } as React.CSSProperties;

    const onMouseEnter = (e: React.MouseEvent) => {
      if (typeof childProps.onMouseEnter === 'function')
        childProps.onMouseEnter(e);
      handleMouseEnter(e as React.MouseEvent<HTMLDivElement>);
    };
    const onMouseLeave = (e: React.MouseEvent) => {
      if (typeof childProps.onMouseLeave === 'function')
        childProps.onMouseLeave(e);
      handleMouseLeave(e as React.MouseEvent<HTMLDivElement>);
    };
    const onPointerDown = (e: React.PointerEvent) => {
      if (typeof childProps.onPointerDown === 'function')
        childProps.onPointerDown(e);
      handlePointerDown(e as React.PointerEvent<HTMLDivElement>);
    };

    const newChildren = (
      <>
        {childProps.children}
        {enable && overlayElement}
      </>
    );

    return React.cloneElement(child, {
      ...props,
      className: mergedClassName,
      style: mergedStyle,
      onMouseEnter,
      onMouseLeave,
      onPointerDown,
      children: newChildren,
    });
  }

  return (
    <div
      style={{ position: 'relative', overflow: 'hidden', ...style }}
      {...props}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onPointerDown={handlePointerDown}
    >
      {children}
      {enable && overlayElement}
    </div>
  );
};

export { Shine, type ShineProps };

'use client';

import * as React from 'react';
import {
  motion,
  type HTMLMotionProps,
  type Transition,
  type Variant,
} from 'motion/react';

import {
  motionTokens,
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';
import {
  useIsInView,
  type UseIsInViewOptions,
} from '../../../utils/use-is-in-view';
import { Slot, type WithAsChild } from '../../slot';

type SlideDirection = 'up' | 'down' | 'left' | 'right';

type SlideProps = WithAsChild<
  {
    children?: React.ReactNode;
    delay?: number;
    direction?: SlideDirection;
    offset?: number;
    ref?: React.Ref<HTMLElement>;
  } & UseIsInViewOptions &
    HTMLMotionProps<'div'>
>;

const DEFAULT_TRANSITION: Transition = motionTokens.spring.entrance;

function Slide(props: SlideProps) {
  return (
    <ReducedMotionConfig remount>
      <SlideInner {...props} />
    </ReducedMotionConfig>
  );
}

function SlideInner({
  ref,
  transition,
  delay = 0,
  inView = false,
  inViewMargin = '0px',
  inViewOnce = true,
  direction = 'up',
  offset = 100,
  asChild = false,
  ...props
}: SlideProps) {
  const defaultTransition = useTempoTransition(DEFAULT_TRANSITION);
  const baseTransition: Transition = transition ?? defaultTransition;
  const { ref: localRef, isInView } = useIsInView(
    ref as React.Ref<HTMLElement>,
    {
      inView,
      inViewOnce,
      inViewMargin,
    },
  );

  const reduce = useShouldReduceMotion();

  const axis = direction === 'up' || direction === 'down' ? 'y' : 'x';
  const hidden: Variant = reduce
    ? { opacity: 0 }
    : {
        [axis]:
          direction === 'right' || direction === 'down' ? -offset : offset,
      };
  const visible: Variant = reduce ? { opacity: 1 } : { [axis]: 0 };

  const Component = asChild ? Slot : motion.div;

  return (
    <Component
      ref={localRef as React.Ref<HTMLDivElement>}
      initial="hidden"
      animate={isInView ? 'visible' : 'hidden'}
      exit="hidden"
      variants={{ hidden, visible }}
      transition={{
        ...baseTransition,
        delay: (baseTransition.delay ?? 0) + delay / 1000,
      }}
      {...props}
    />
  );
}

type SlideListProps = Omit<SlideProps, 'children'> & {
  children: React.ReactElement | React.ReactElement[];
  holdDelay?: number;
};

function Slides({
  children,
  delay = 0,
  holdDelay = 0,
  ...props
}: SlideListProps) {
  const array = React.Children.toArray(children) as React.ReactElement[];

  return (
    <>
      {array.map((child, index) => (
        <Slide
          key={child.key ?? index}
          delay={delay + index * holdDelay}
          {...props}
        >
          {child}
        </Slide>
      ))}
    </>
  );
}

export {
  Slide,
  Slides,
  type SlideProps,
  type SlideListProps,
  type SlideDirection,
};

'use client';

import * as React from 'react';
import { flushSync } from 'react-dom';

import {
  ReducedMotionConfig,
  useMotionTokens,
  useShouldReduceMotion,
} from '../../../utils/motion';

type ThemeSelection = 'light' | 'dark' | 'system';
type Resolved = 'light' | 'dark';
type Direction = 'btt' | 'ttb' | 'ltr' | 'rtl';

type ChildrenRender =
  | React.ReactNode
  | ((state: {
      resolved: Resolved;
      effective: ThemeSelection;
      toggleTheme: (theme: ThemeSelection) => void;
    }) => React.ReactNode);

function getSystemEffective(): Resolved {
  if (typeof window === 'undefined') return 'light';
  return window.matchMedia('(prefers-color-scheme: dark)').matches
    ? 'dark'
    : 'light';
}

function getClipKeyframes(direction: Direction): [string, string] {
  switch (direction) {
    case 'ltr':
      return ['inset(0 100% 0 0)', 'inset(0 0 0 0)'];
    case 'rtl':
      return ['inset(0 0 0 100%)', 'inset(0 0 0 0)'];
    case 'ttb':
      return ['inset(0 0 100% 0)', 'inset(0 0 0 0)'];
    case 'btt':
      return ['inset(100% 0 0 0)', 'inset(0 0 0 0)'];
    default:
      return ['inset(0 100% 0 0)', 'inset(0 0 0 0)'];
  }
}

type ThemeTogglerProps = {
  theme: ThemeSelection;
  resolvedTheme: Resolved;
  setTheme: (theme: ThemeSelection) => void;
  direction?: Direction;
  onImmediateChange?: (theme: ThemeSelection) => void;
  children?: ChildrenRender;
};

const WIPE_DURATION = 700;
const WIPE_EASING = 'ease-in-out';

function subscribeToNothing() {
  return () => {};
}

function useIsMounted() {
  return React.useSyncExternalStore(
    subscribeToNothing,
    () => true,
    () => false,
  );
}

const PLACEHOLDER_STATE = {
  effective: 'system',
  resolved: 'light',
} as const satisfies { effective: ThemeSelection; resolved: Resolved };

function ThemeToggler(props: ThemeTogglerProps) {
  return (
    <ReducedMotionConfig>
      <ThemeTogglerInner {...props} />
    </ReducedMotionConfig>
  );
}

function ThemeTogglerInner({
  theme,
  resolvedTheme,
  setTheme,
  onImmediateChange,
  direction = 'ltr',
  children,
  ...props
}: ThemeTogglerProps) {
  const mounted = useIsMounted();
  const reduce = useShouldReduceMotion();
  const tokens = useMotionTokens();
  const wipeDuration = WIPE_DURATION * tokens.tempo;
  const [preview, setPreview] = React.useState<null | {
    effective: ThemeSelection;
    resolved: Resolved;
  }>(null);
  const [current, setCurrent] = React.useState<{
    effective: ThemeSelection;
    resolved: Resolved;
  }>({
    effective: theme,
    resolved: resolvedTheme,
  });

  React.useEffect(() => {
    setCurrent({ effective: theme, resolved: resolvedTheme });
  }, [theme, resolvedTheme]);

  React.useEffect(() => {
    if (
      preview &&
      theme === preview.effective &&
      resolvedTheme === preview.resolved
    ) {
      setPreview(null);
    }
  }, [theme, resolvedTheme, preview]);

  const [fromClip, toClip] = getClipKeyframes(direction);

  const toggleTheme = React.useCallback(
    async (theme: ThemeSelection) => {
      const resolved = theme === 'system' ? getSystemEffective() : theme;

      setCurrent({ effective: theme, resolved });
      onImmediateChange?.(theme);

      if (theme === 'system' && resolved === resolvedTheme) {
        setTheme(theme);
        return;
      }

      if (reduce || !document.startViewTransition) {
        flushSync(() => {
          setPreview({ effective: theme, resolved });
        });
        setTheme(theme);
        return;
      }

      await document.startViewTransition(() => {
        flushSync(() => {
          setPreview({ effective: theme, resolved });
          document.documentElement.classList.toggle(
            'dark',
            resolved === 'dark',
          );
        });
      }).ready;

      document.documentElement
        .animate(
          { clipPath: [fromClip, toClip] },
          {
            duration: wipeDuration,
            easing: WIPE_EASING,
            pseudoElement: '::view-transition-new(root)',
          },
        )
        .finished.finally(() => {
          setTheme(theme);
        });
    },
    [
      onImmediateChange,
      resolvedTheme,
      fromClip,
      toClip,
      setTheme,
      reduce,
      wipeDuration,
    ],
  );

  const state = mounted ? current : PLACEHOLDER_STATE;

  return (
    <React.Fragment {...props}>
      {typeof children === 'function'
        ? children({
            effective: state.effective,
            resolved: state.resolved,
            toggleTheme,
          })
        : children}
      <style>{`::view-transition-old(root), ::view-transition-new(root){animation:none;mix-blend-mode:normal;}`}</style>
    </React.Fragment>
  );
}

export {
  ThemeToggler,
  type ThemeTogglerProps,
  type ThemeSelection,
  type Resolved,
  type Direction,
};

'use client';

import * as React from 'react';
import {
  motion,
  useMotionValue,
  useSpring,
  type MotionValue,
  type SpringOptions,
  type HTMLMotionProps,
} from 'motion/react';

import {
  ReducedMotionConfig,
  useShouldReduceMotion,
} from '../../../utils/motion';
import { getStrictContext } from '../../../utils/strict-context';
import { Slot, type WithAsChild } from '../../slot';

type TiltContextType = {
  sRX: MotionValue<number>;
  sRY: MotionValue<number>;
  transition: SpringOptions;
};

const [TiltProvider, useTilt] =
  getStrictContext<TiltContextType>('TiltContext');

type TiltProps = WithAsChild<
  HTMLMotionProps<'div'> & {
    maxTilt?: number;
    perspective?: number;
    transition?: SpringOptions;
  }
>;

function Tilt(props: TiltProps) {
  return (
    <ReducedMotionConfig>
      <TiltInner {...props} />
    </ReducedMotionConfig>
  );
}

function TiltInner({
  maxTilt = 10,
  perspective = 800,
  style,
  transition = {
    stiffness: 300,
    damping: 25,
    mass: 0.5,
  },
  onMouseMove,
  onMouseLeave,
  asChild = false,
  ...props
}: TiltProps) {
  const reduce = useShouldReduceMotion();
  const rX = useMotionValue(0);
  const rY = useMotionValue(0);

  const sRX = useSpring(rX, transition);
  const sRY = useSpring(rY, transition);

  const handleMouseMove = React.useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      onMouseMove?.(e);
      if (reduce) return;
      const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
      const px = (e.clientX - rect.left) / rect.width;
      const py = (e.clientY - rect.top) / rect.height;
      const nx = px * 2 - 1;
      const ny = py * 2 - 1;
      rY.set(nx * maxTilt);
      rX.set(-ny * maxTilt);
    },
    [maxTilt, rX, rY, onMouseMove, reduce],
  );

  const handleMouseLeave = React.useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      onMouseLeave?.(e);
      rX.set(0);
      rY.set(0);
    },
    [rX, rY, onMouseLeave],
  );

  React.useEffect(() => {
    if (!reduce) return;
    rX.jump(0);
    rY.jump(0);
    sRX.jump(0);
    sRY.jump(0);
  }, [reduce, rX, rY, sRX, sRY]);

  const Comp = asChild ? Slot : motion.div;

  return (
    <TiltProvider value={{ sRX, sRY, transition }}>
      <Comp
        style={{
          perspective,
          transformStyle: 'preserve-3d',
          willChange: 'transform',
          ...style,
        }}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        {...props}
      />
    </TiltProvider>
  );
}

type TiltContentProps = WithAsChild<HTMLMotionProps<'div'>>;

function TiltContent({
  children,
  style,
  transition,
  asChild = false,
  ...props
}: TiltContentProps) {
  const { sRX, sRY, transition: tiltTransition } = useTilt();

  const Comp = asChild ? Slot : motion.div;

  return (
    <Comp
      style={{
        rotateX: sRX,
        rotateY: sRY,
        willChange: 'transform',
        ...style,
      }}
      transition={transition ?? tiltTransition}
      {...props}
    >
      {children}
    </Comp>
  );
}

export { Tilt, TiltContent, type TiltProps, type TiltContentProps };

