function cn(...classes: (string | false | null | undefined)[]) {
  return classes.filter(Boolean).join(' ') || undefined;
}

type GithubStarsContextType = {
  stars: number;
  setStars: (stars: number) => void;
  currentStars: number;
  setCurrentStars: (stars: number) => void;
  isCompleted: boolean;
  isLoading: boolean;
};

const [GithubStarsProvider, useGithubStars] =
  getStrictContext<GithubStarsContextType>('GithubStarsContext');

type GithubStarsProps = WithAsChild<
  {
    children: React.ReactNode;
    username?: string;
    repo?: string;
    value?: number;
    delay?: number;
  } & UseIsInViewOptions &
    HTMLMotionProps<'div'>
>;

function GithubStars({
  ref,
  children,
  username,
  repo,
  value,
  delay = 0,
  inView = false,
  inViewMargin = '0px',
  inViewOnce = true,
  asChild = false,
  ...props
}: GithubStarsProps) {
  const { ref: localRef, isInView } = useIsInView(
    ref as React.Ref<HTMLDivElement>,
    { inView, inViewOnce, inViewMargin },
  );

  const [stars, setStars] = React.useState(value ?? 0);
  const [currentStars, setCurrentStars] = React.useState(0);
  const [isLoading, setIsLoading] = React.useState(true);
  const isCompleted = React.useMemo(
    () => currentStars === stars,
    [currentStars, stars],
  );

  const Component = asChild ? Slot : motion.div;

  React.useEffect(() => {
    if (value !== undefined) {
      setStars(value);
      setIsLoading(false);
      return;
    }
    setStars(0);
    setIsLoading(true);
    if (!isInView || !username || !repo) return;

    const controller = new AbortController();
    const timeout = setTimeout(() => {
      fetch(`https://api.github.com/repos/${username}/${repo}`, {
        signal: controller.signal,
      })
        .then((response) => {
          if (!response.ok)
            throw new Error(`GitHub API responded ${response.status}`);
          return response.json();
        })
        .then((data) => {
          if (typeof data?.stargazers_count !== 'number')
            throw new Error('GitHub API sent no star count');
          setStars(data.stargazers_count);
          setIsLoading(false);
        })
        .catch((error) => {
          if (!controller.signal.aborted)
            console.error(
              'Animate UI GithubStars: could not load stars',
              error,
            );
        });
    }, delay);

    return () => {
      clearTimeout(timeout);
      controller.abort();
    };
  }, [username, repo, value, isInView, delay]);

  return (
    <GithubStarsProvider
      value={{
        stars,
        currentStars,
        isCompleted,
        isLoading,
        setStars,
        setCurrentStars,
      }}
    >
      {asChild ? (
        <Component
          ref={localRef}
          aria-busy={isLoading || undefined}
          {...props}
          style={
            isLoading ? { ...props.style, visibility: 'hidden' } : props.style
          }
        >
          {children}
        </Component>
      ) : (
        <Component ref={localRef} aria-busy={isLoading || undefined} {...props}>
          {!isLoading && children}
        </Component>
      )}
    </GithubStarsProvider>
  );
}

type GithubStarsNumberProps = Omit<SlidingNumberProps, 'number' | 'fromNumber'>;

function GithubStarsNumber({
